import Foundation

enum LabProvider: String, CaseIterable, Identifiable {
    case idexx = "IDEXX"
    case msu = "MSU"
    var id: String { rawValue }
    var title: String { self == .idexx ? "IDEXX Reference Laboratories" : "Michigan State VDL" }
}
struct LabTestEntry: Identifiable {
    let id, provider, code, name, purpose, species, specimen, amount, tube, preparation, handling, notes, source: String
