        return tests.filter { item in
            guard provider == nil || item.provider == provider?.rawValue else { return false }
            let text = [item.name,item.code,item.provider,item.purpose,item.species,item.specimen,item.tube,item.notes,item.components,preparation(item.preparation), item.provider == "MSU" ? "Michigan State" : "IDEXX"].joined(separator: " ").folding(options: [.caseInsensitive,.diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
